"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$targets = @(169376, 166340, 100668)
foreach ($id in $targets) {
  $process = Get-Process -Id $id -ErrorAction SilentlyContinue
  if ($null -ne $process) { Stop-Process -Id $id -Force }
}
Start-Sleep -Milliseconds 500
Get-Process -Id $targets -ErrorAction SilentlyContinue | Select-Object Id,ProcessName,Path'

